// Utility functions
export function getRaceTemplateByName(name: string): RaceTemplate | undefined {
  return RACE_TEMPLATES_LIBRARY.find(race => race.race_name === name);
}

export function getRaceTemplateByKey(key: string): RaceTemplate | undefined {
  return RACE_TEMPLATES_LIBRARY.find(race =>
    race.race_name.toLowerCase().replace(/\s+/g, '-') === key.toLowerCase()
  );
}

export function searchRaceTemplates(query: string): RaceTemplate[] {
  const searchTerm = query.toLowerCase();
  return RACE_TEMPLATES_LIBRARY.filter(race =>
    race.race_name.toLowerCase().includes(searchTerm) ||
    race.attributes.some(attr =>
      (attr.custom_name || '').toLowerCase().includes(searchTerm) ||
      (attr.user_description || '').toLowerCase().includes(searchTerm)
    )
  );
}

export function getAllRaceTemplates(): RaceTemplate[] {
  return [...RACE_TEMPLATES_LIBRARY];
}
